#!/usr/bin/env node
// .githooks/hooks/block-forbidden-files.js
// Reject writes to files that must not be edited by the agent.

const path = require('path');

const forbidden = [
  { pattern: /(^|\/)\.env$/, reason: 'Real secrets must not be committed. Edit .env.example only.' },
  { pattern: /(^|\/)\.env\.local$/, reason: 'Local env files are not committed.' },
  { pattern: /appsettings\.Production\.json$/, reason: 'Production config is owned by the user. Propose the change in the PR description.' },
  { pattern: /(^|\/)rbac_policy\.csv$/, reason: 'RBAC policy changes go through a labeled PR (feat(rbac): …).' },
  { pattern: /backend\/.*\/Migrations\/.*\.cs$/, reason: 'Migrations are owned by `dotnet ef migrations add`. Hand-edits blocked.' },
];

function isForbidden(filePath) {
  if (!filePath) return null;
  const normalized = filePath.replace(/\\/g, '/');
  for (const rule of forbidden) {
    if (rule.pattern.test(normalized)) return rule.reason;
  }
  return null;
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let payload = {};
  try {
    payload = JSON.parse(input);
  } catch {
    // No payload — allow.
    process.exit(0);
  }

  const candidates = [
    payload.path,
    payload.filePath,
    payload.file,
    payload.arguments && payload.arguments.path,
  ].filter(Boolean);

  for (const candidate of candidates) {
    const reason = isForbidden(candidate);
    if (reason) {
      process.stderr.write(`❌ BLOCKED: ${candidate} — ${reason}\n`);
      process.exit(2);
    }
  }

  process.exit(0);
});

#!/usr/bin/env node
// .githooks/hooks/block-destructive-commands.js
// Reject terminal commands that could damage the system, push to main, or update a non-dev DB.

const forbidden = [
  {
    pattern: /\brm\s+-rf?\b(?!\s+(node_modules|\.next|bin|obj|dist|\.pytest_cache|__pycache__))/,
    reason: 'rm -rf is only allowed inside safe build/cache directories.',
  },
  { pattern: /git\s+push\s+--force\b.*\b(main|master)\b/, reason: 'Force-push to main is forbidden.' },
  { pattern: /git\s+push\s+-f\b.*\b(main|master)\b/, reason: 'Force-push to main is forbidden.' },
  {
    pattern: /dotnet\s+ef\s+database\s+update\b/,
    reason: 'Run `dotnet ef database update` manually, not from an agent. Use migrations script + review first.',
    // Allow only when explicitly scoped to a dev connection string.
    exception: (cmd) => /Data\s*Source\s*=\s*data\//i.test(cmd) || /Data\s*Source\s*=\s*:memory:/i.test(cmd),
  },
  {
    pattern: /--env\s+production\b/,
    reason: 'Commands that target the production environment are not run by the agent.',
  },
];

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let payload = {};
  try {
    payload = JSON.parse(input);
  } catch {
    process.exit(0);
  }

  const cmd = (payload.command || '').toString();

  for (const rule of forbidden) {
    if (rule.pattern.test(cmd)) {
      if (rule.exception && rule.exception(cmd)) continue;
      process.stderr.write(`❌ BLOCKED command: ${cmd}\n   ${rule.reason}\n`);
      process.exit(2);
    }
  }

  process.exit(0);
});

#!/usr/bin/env node
// .githooks/hooks/verify-migration-shape.js
// After a 'dotnet ef migrations add' command, verify the generated migration
// has both Up and Down methods. This is a soft check: warn, don't block.

const fs = require('fs');
const path = require('path');

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let payload = {};
  try {
    payload = JSON.parse(input);
  } catch {
    process.exit(0);
  }

  const cmd = (payload.command || '').toString();
  if (!/\bdotnet\s+ef\s+migrations\s+add\b/.test(cmd)) {
    process.exit(0);
  }

  // Find the latest .cs file in the Migrations directory.
  const migrationsDir = path.resolve(
    process.cwd(),
    'backend/src/SonrisaNews.Infrastructure/Migrations'
  );

  if (!fs.existsSync(migrationsDir)) {
    process.stderr.write(`⚠️  Migrations directory not found: ${migrationsDir}\n`);
    process.exit(0);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((f) => /^\d{14}_.*\.cs$/.test(f))
    .sort()
    .reverse();

  if (files.length === 0) {
    process.stderr.write('⚠️  No migration files found.\n');
    process.exit(0);
  }

  const latest = path.join(migrationsDir, files[0]);
  const content = fs.readFileSync(latest, 'utf8');

  const hasUp = /protected\s+override\s+void\s+Up\s*\(/.test(content);
  const hasDown = /protected\s+override\s+void\s+Down\s*\(/.test(content);
  const hasForwardOnly = /\/\/\s*Forward-only after merge\./.test(content);

  const issues = [];
  if (!hasUp) issues.push('missing `Up` method');
  if (!hasDown) issues.push('missing `Down` method');
  if (!hasForwardOnly) issues.push('missing `// Forward-only after merge.` comment in `Up`');

  if (issues.length > 0) {
    process.stderr.write(`⚠️  Migration ${files[0]} has issues: ${issues.join(', ')}.\n`);
    process.exit(0); // Soft warning — don't block; the TDD agent will fix it.
  }

  process.stderr.write(`✅ Migration ${files[0]} looks correct.\n`);
  process.exit(0);
});

#!/usr/bin/env node
// .githooks/hooks/secret-pattern-scan.js
// Scan new/edited file content for common secret patterns.
// Allow explicit test fixtures by checking for a 'TEST-ONLY' marker on the same line.

const secretPatterns = [
  { name: 'AWS access key', regex: /AKIA[0-9A-Z]{16}/ },
  { name: 'GitHub personal access token', regex: /ghp_[0-9a-zA-Z]{36}/ },
  { name: 'Resend API key', regex: /re_[0-9a-zA-Z]{20,}/ },
  { name: 'Slack token', regex: /xox[baprs]-[0-9a-zA-Z-]{10,}/ },
  { name: 'PEM private key', regex: /-----BEGIN [A-Z ]*PRIVATE KEY-----/ },
  { name: 'Stripe live key', regex: /sk_live_[0-9a-zA-Z]{24,}/ },
];

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let payload = {};
  try {
    payload = JSON.parse(input);
  } catch {
    process.exit(0);
  }

  const content =
    (payload.content || '').toString() +
    '\n' +
    ((payload.newText || payload.new_str || '').toString());

  if (!content.trim()) {
    process.exit(0);
  }

  for (const { name, regex } of secretPatterns) {
    const match = content.match(regex);
    if (!match) continue;

    // Allow if the same line has a 'TEST-ONLY' or 'FAKE' marker — the developer
    // is intentionally using a fake value. This is a heuristic, not a guarantee.
    const lineIndex = content.slice(0, match.index).split('\n').length;
    const line = content.split('\n')[lineIndex - 1] || '';
    if (/TEST-ONLY|FAKE|DUMMY|EXAMPLE/i.test(line)) continue;

    process.stderr.write(
      `❌ BLOCKED: possible ${name} in new/edited content.\n` +
        `   Line ${lineIndex}: ${line.trim().slice(0, 80)}…\n` +
        `   If this is a test fixture, add a 'TEST-ONLY' comment on the same line.\n`
    );
    process.exit(2);
  }

  process.exit(0);
});

